#' Run MEGSA
#'
#' Identifies mutually exclusive gene sets from a binary mutation matrix.
#'
#' @param mutationMat A logical or numeric matrix with samples in rows and
#'   genes in columns. Non-zero numeric values are treated as mutations.
#' @param maxSSimu Optional null-distribution matrix generated by
#'   [funMaxSSimu()]. Rows are simulations and columns correspond to gene-set
#'   sizes 2 through `maxSize`.
#' @param nSimu Number of simulations to run when `maxSSimu` is not supplied.
#' @param nPairStart Number of starting gene pairs for the forward search.
#' @param maxSize Maximum size of a mutually exclusive gene set.
#' @param level Family-wise error rate threshold.
#' @param detail If `TRUE`, print progress messages.
#' @param search Search strategy. `"screened"` uses the 2016 correlation
#'   screening heuristic; `"exhaustive"` evaluates all candidate pairs and
#'   additions as in the earlier script release.
#' @param ncores Number of parallel worker processes for simulations.
#' @param seed Optional random seed for simulation reproducibility.
#' @param resultTableFile Optional output path for a tab-delimited MEGS table.
#' @param figureDir Optional output directory for MEGS plots.
#' @param type Figure file type: `"pdf"`, `"png"`, or `"jpg"`.
#'
#' @return A list with global p-value `p` and significant mutually exclusive
#'   gene sets in `MEGSList`.
#'
#' @references Hua X, Hyland PL, Huang J, Song L, Zhu B, Caporaso NE,
#'   Landi MT, Chatterjee N, Shi J. 2016. MEGSA: A powerful and flexible
#'   framework for analyzing mutual exclusivity of tumor mutations. *The
#'   American Journal of Human Genetics* 98(3):442-455.
#'   <https://doi.org/10.1016/j.ajhg.2015.12.021>
#'
#' @export
megsa <- function(mutationMat, maxSSimu = NULL, nSimu = 1000,
                  nPairStart = 10, maxSize = 6, level = 0.05,
                  detail = FALSE, search = c("screened", "exhaustive"),
                  ncores = 1, seed = NULL, resultTableFile = NULL,
                  figureDir = NULL, type = "pdf") {
  mutationMat <- normalize_mutation_matrix(mutationMat)
  maxSSimu <- normalize_max_simu_matrix(maxSSimu)
  result <- funSelect(
    mutationMat = mutationMat,
    maxSSimu = maxSSimu,
    nSimu = nSimu,
    nPairStart = nPairStart,
    maxSize = maxSize,
    level = level,
    detail = detail,
    search = search,
    ncores = ncores,
    seed = seed
  )

  if (!is.null(resultTableFile)) {
    funPrintMEGS(result$MEGSList, outputFile = resultTableFile)
  }
  if (!is.null(figureDir)) {
    funPlotMEGS(result$MEGSList, mutationMat, outputDir = figureDir, type = type)
  }

  structure(result, class = c("megsa", class(result)))
}

#' Run MEGSA from files
#'
#' @inheritParams megsa
#' @param mutationMatFile Path to a tab-delimited mutation matrix. The first
#'   row contains gene names and the first column contains sample IDs.
#' @param maxSSimuFile Optional path to a tab-delimited null-distribution
#'   matrix.
#'
#' @return A MEGSA result object.
#'
#' @export
megsa_file <- function(mutationMatFile, maxSSimuFile = NULL, nSimu = 1000,
                       nPairStart = 10, maxSize = 6, level = 0.05,
                       detail = FALSE, search = c("screened", "exhaustive"),
                       ncores = 1, seed = NULL, resultTableFile = NULL,
                       figureDir = NULL, type = "pdf") {
  mutationMat <- read_megsa_mutation_matrix(mutationMatFile)
  maxSSimu <- if (is.null(maxSSimuFile)) {
    NULL
  } else {
    read_megsa_max_simu(maxSSimuFile)
  }

  megsa(
    mutationMat = mutationMat,
    maxSSimu = maxSSimu,
    nSimu = nSimu,
    nPairStart = nPairStart,
    maxSize = maxSize,
    level = level,
    detail = detail,
    search = search,
    ncores = ncores,
    seed = seed,
    resultTableFile = resultTableFile,
    figureDir = figureDir,
    type = type
  )
}

